// The design drawings as vector XAML (Art/*.xaml, generated by tools/art). Loaded on demand per family and
// theme, then composed at run time: the scene for where each pod is (in the case / out) + the case light.

using System.IO;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Earbuds.Presentation;

namespace Earbuds.App.Art;

public static class ArtLibrary
{
    private static readonly Dictionary<string, ResourceDictionary> Dicts = new();
    private static readonly Dictionary<string, ImageSource> Images = new();

    private static string FamilyName(ArtFamily f) => f switch
    {
        ArtFamily.Short => "short",
        ArtFamily.Long => "long",
        ArtFamily.Pro => "pro",
        ArtFamily.Max => "max",
        _ => "generic",
    };

    private static ResourceDictionary Dict(string name)
    {
        if (!Dicts.TryGetValue(name, out var d))
        {
            d = new ResourceDictionary { Source = new Uri("/Art/Art." + name + ".xaml", UriKind.Relative) };
            Dicts[name] = d;
        }

        return d;
    }

    /// <summary>The open case with both pods (or AirPods Max), as the model says.</summary>
    public static ImageSource Scene(ArtModel art, bool dark)
    {
        var theme = dark ? "dark" : "light";
        var key = $"{FamilyName(art.Family)}.{art.LeftOut}.{art.RightOut}.{art.Led}.{theme}";
        if (Images.TryGetValue(key, out var cached))
        {
            return cached;
        }

        ImageSource image;
        if (art.Family == ArtFamily.Max)
        {
            image = (ImageSource)Dict("max." + theme)["max"];
        }
        else
        {
            var fam = FamilyName(art.Family);
            var scene = (DrawingImage)Dict(fam + "." + theme)["scene." + (art.LeftOut ? "o" : "c") + (art.RightOut ? "o" : "c")];
            if (art.Led == LedState.Off || art.Family == ArtFamily.Generic)
            {
                image = scene;
            }
            else
            {
                var led = (DrawingImage)Dict("leds")["led." + fam + (art.Led == LedState.Amber ? ".a" : ".g")];
                var group = new DrawingGroup();
                group.Children.Add(scene.Drawing);
                group.Children.Add(led.Drawing);
                var composed = new DrawingImage(group);
                composed.Freeze();
                image = composed;
            }
        }

        Images[key] = image;
        return image;
    }

    /// <summary>One pod alone (notification picture). side: 'l' or 'r'.</summary>
    public static ImageSource Bud(ArtFamily family, char side, bool dark)
    {
        if (family == ArtFamily.Max)
        {
            return (ImageSource)Dict("max." + (dark ? "dark" : "light"))["max"];
        }

        return (ImageSource)Dict(FamilyName(family) + "." + (dark ? "dark" : "light"))["bud." + side];
    }

    public static ImageSource AppIcon => (ImageSource)Dict("appicon")["appicon"];

    /// <summary>Renders an image to a PNG file (for Windows notifications, which need a file).</summary>
    public static void SavePng(string path, IReadOnlyList<ImageSource> parts, double height, double gap, double scale = 2)
    {
        var widths = parts.Select(p => p.Width / p.Height * height).ToList();
        var width = widths.Sum() + gap * (parts.Count - 1);
        var visual = new DrawingVisual();
        using (var dc = visual.RenderOpen())
        {
            dc.PushTransform(new ScaleTransform(scale, scale));
            double x = 0;
            for (var i = 0; i < parts.Count; i++)
            {
                dc.DrawImage(parts[i], new Rect(x, 0, widths[i], height));
                x += widths[i] + gap;
            }

            dc.Pop();
        }

        var bmp = new RenderTargetBitmap((int)Math.Ceiling(width * scale), (int)Math.Ceiling(height * scale), 96, 96, PixelFormats.Pbgra32);
        bmp.Render(visual);
        var encoder = new PngBitmapEncoder();
        encoder.Frames.Add(BitmapFrame.Create(bmp));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        using var file = File.Create(path);
        encoder.Save(file);
    }
}
